261		}
262		if adjusted.PlannedPortions != 3 || adjusted.Status != StatusDraft {
263			t.Fatalf("调整结果不正确: %+v", adjusted)
264		}
265	
266		// 执行中尚未投料、已关闭无投料都正常。
267		for _, batchNo := range []string{"B-exec", "B-closed-empty"} {
268			view, err := s.GetBatch(batchNo)
269			if err != nil {
270				t.Fatalf("查询 %q 失败: %v", batchNo, err)
271			}
272			if len(view.Feedings) != 0 || view.Materials[0].ActualGrams != "0" {
273				t.Fatalf("%q 应无投料: %+v", batchNo, view)
274			}
275		}
276		// 已关闭批次的欠投、超投原样保留，关闭门槛不提高。
277		under, err := s.GetBatch("B-closed-under")
278		if err != nil {
279			t.Fatal(err)
280		}
281		if under.Materials[0].ActualGrams != "40" || under.Materials[0].DifferenceGrams != "-60" {
282			t.Fatalf("欠投应原样保留: %+v", under.Materials[0])
283		}
284		over, err := s.GetBatch("B-closed-over")
285		if err != nil {
286			t.Fatal(err)
287		}
288		if over.Materials[0].ActualGrams != "150" || over.Materials[0].DifferenceGrams != "50" {
289			t.Fatalf("超投应原样保留: %+v", over.Materials[0])
290		}
291	}
