156	// 沿用已成功使用的请求编号时，批次、物料、克数字符串、投料时间或登记人
157	// 任一项改变，都必须返回 ErrRequestConflict（可用 errors.Is 判断）。
158	// 这里每个改动本身都符合投料条件：改投同一配方中的另一种物料、换一个合法
159	// 数量、更换登记人、换一个投料时间，或改到另一个同样处于执行中的批次，
160	// 不靠非法输入被拒来代表请求冲突。内容不同的提交不能覆盖原投料、不能追加
161	// 新投料、不能占用下一个登记序号。
162	func TestAddFeedingRequestConflictOnAnyContentChange(t *testing.T) {
163		s := openTestStore(t)
164		registerStandardRecipe(t, s, "recipe-1")
165		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
166			t.Fatalf("创建 B1 失败: %v", err)
167		}
168		if _, err := s.StartBatch("s1", "B1"); err != nil {
169			t.Fatalf("开始执行 B1 失败: %v", err)
170		}
171		// 另一个同样处于执行中的批次 B2，绑定同一配方版本，使“改批次”的
172		// 提交本身也是一笔合法投料。
173		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
174			t.Fatalf("创建 B2 失败: %v", err)
175		}
176		if _, err := s.StartBatch("s2", "B2"); err != nil {
177			t.Fatalf("开始执行 B2 失败: %v", err)
178		}
179	
180		t1 := feedingReplayTime()
181		first, err := s.AddFeeding("feed-orig", "B1", "M1", "10", t1, "张三")
182		if err != nil {
183			t.Fatalf("首次登记投料应成功: %v", err)
184		}
185		checkFeedingView(t, first, 1, "M1", "10", t1, "张三")
186		// 再追加一笔，占用序号 2，便于发现冲突提交是否偷偷追加或占号。
187		if _, err := s.AddFeeding("feed-other", "B1", "M2", "2", t1.Add(time.Hour), "李四"); err != nil {
188			t.Fatalf("追加第二笔投料失败: %v", err)
189		}
190	
191		// 每项都只改一处，其余与首次成功提交完全一致，且改后内容仍可正常投料。
192		cases := []struct {
193			name      string
194			batchNo   string
195			material  string
196			grams     string
197			tm        time.Time
198			registrar string
199		}{
200			{name: "改投同一配方中的另一种物料", batchNo: "B1", material: "M2", grams: "10", tm: t1, registrar: "张三"},
201			{name: "换一个合法数量", batchNo: "B1", material: "M1", grams: "11", tm: t1, registrar: "张三"},
202			{name: "更换投料时间", batchNo: "B1", material: "M1", grams: "10", tm: t1.Add(time.Minute), registrar: "张三"},
203			{name: "更换登记人", batchNo: "B1", material: "M1", grams: "10", tm: t1, registrar: "李四"},
204			{name: "改到另一个执行中的批次", batchNo: "B2", material: "M1", grams: "10", tm: t1, registrar: "张三"},
205		}
206		for _, tc := range cases {
207			t.Run(tc.name, func(t *testing.T) {
208				_, err := s.AddFeeding("feed-orig", tc.batchNo, tc.material, tc.grams, tc.tm, tc.registrar)
209				if !errors.Is(err, ErrRequestConflict) {
210					t.Fatalf("内容不同但沿用原请求编号应返回 ErrRequestConflict，得到 %v", err)
211				}
212			})
213	
214			// 每次冲突后 B1 都保持原样：仍是 2 条投料、顺序不变，
215			// M1 累计仍为 10、M2 累计仍为 2，冲突内容没有被追加或覆盖。
216			view := mustGetBatch(t, s, "B1")
217			if len(view.Feedings) != 2 {
218				t.Fatalf("%s：冲突不应追加投料，B1 应仍为 2 条，得到 %d 条: %+v",
219					tc.name, len(view.Feedings), view.Feedings)
220			}
221			checkFeedingView(t, &view.Feedings[0], 1, "M1", "10", t1, "张三")
222			checkFeedingView(t, &view.Feedings[1], 2, "M2", "2", t1.Add(time.Hour), "李四")
223			b1Mats := materialsMap(view)
224			checkRequirement(t, b1Mats, "M1", "1000", "10", "-990")
225			checkRequirement(t, b1Mats, "M2", "5", "2", "-3")
226			checkRequirement(t, b1Mats, "M3", "0.1", "0", "-0.1")
227	
228			// 下一个登记序号不能被冲突占用：B2 的“改批次”冲突同样不能落进 B2。
229			b2 := mustGetBatch(t, s, "B2")
230			if len(b2.Feedings) != 0 {
231				t.Fatalf("%s：冲突不应在 B2 追加投料，得到 %d 条: %+v",
232					tc.name, len(b2.Feedings), b2.Feedings)
233			}
234		}
235	
236		// 全部冲突之后，原内容用原编号仍取得第一次成功结果，不是最近一笔。
237		replay, err := s.AddFeeding("feed-orig", "B1", "M1", "10", t1, "张三")
238		if err != nil {
239			t.Fatalf("冲突后原内容重放应成功: %v", err)
240		}
241		checkFeedingView(t, replay, 1, "M1", "10", t1, "张三")
242	}
243	
244	// 克数的显示格式与请求内容必须分清：首次提交“1.000”克，成功结果显示“1”克；
245	// 再次提交仍带“1.000”时能取回原结果；改成“1”（或“1.0”）时即使数值相等，
246	// 也属于不同内容，必须返回 ErrRequestConflict。冲突后原内容仍可取得原结果，
247	// 且批次中始终只有首次那一笔投料。
248	func TestAddFeedingGramsFormatIsPartOfRequestContent(t *testing.T) {
249		s := openTestStore(t)
250		registerStandardRecipe(t, s, "recipe-1")
251		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
252			t.Fatalf("创建批次失败: %v", err)
253		}
254		if _, err := s.StartBatch("s1", "B1"); err != nil {
255			t.Fatalf("开始执行失败: %v", err)
256		}
257	
258		t1 := feedingReplayTime()
259		first, err := s.AddFeeding("feed-fmt", "B1", "M1", "1.000", t1, "张三")
260		if err != nil {
261			t.Fatalf("首次登记 1.000 克应成功: %v", err)
262		}
263		// 存储以千分之一克定点表示，成功结果去掉末尾多余的 0，显示为“1”。
264		checkFeedingView(t, first, 1, "M1", "1", t1, "张三")
265	
266		// 仍带原字符串“1.000”重放：同一内容，取回原结果，不重复计入实投。
267		replay, err := s.AddFeeding("feed-fmt", "B1", "M1", "1.000", t1, "张三")
268		if err != nil {
269			t.Fatalf("仍带 1.000 重放应返回原结果: %v", err)
270		}
271		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
272	
273		// 改成数值相等但字符串不同的“1”：请求内容不同，必须判冲突，
274		// 不能按数值相等当成同一笔投料重放。
275		if _, err := s.AddFeeding("feed-fmt", "B1", "M1", "1", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
276			t.Fatalf("1.000 改成数值相等的 1 应返回 ErrRequestConflict，得到 %v", err)
277		}
278		// “1.0”同样只是显示格式不同、数值相等，也属于不同内容。
279		if _, err := s.AddFeeding("feed-fmt", "B1", "M1", "1.0", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
280			t.Fatalf("1.000 改成数值相等的 1.0 应返回 ErrRequestConflict，得到 %v", err)
281		}
282	
283		// 冲突之后，原字符串“1.000”仍能取得第一次的结果。
284		replayAgain, err := s.AddFeeding("feed-fmt", "B1", "M1", "1.000", t1, "张三")
285		if err != nil {
286			t.Fatalf("冲突后原内容应仍可重放: %v", err)
287		}
288		checkFeedingView(t, replayAgain, 1, "M1", "1", t1, "张三")
289	
290		// 批次始终只有首次那一笔投料，M1 累计实投为 1，没有被数值相等的
291		// 冲突提交重复计入。
292		view := mustGetBatch(t, s, "B1")
293		if len(view.Feedings) != 1 {
294			t.Fatalf("冲突提交不应追加投料，应只有 1 条，得到 %d 条: %+v",
295				len(view.Feedings), view.Feedings)
296		}
297		checkFeedingView(t, &view.Feedings[0], 1, "M1", "1", t1, "张三")
298		mats := materialsMap(view)
299		checkRequirement(t, mats, "M1", "1000", "1", "-999")
300		checkRequirement(t, mats, "M2", "5", "0", "-5")
301	}
302	
303	// 请求编号在同一台账内共用：另一个同样处于执行中的批次也不能沿用这个编号
304	// 登记投料。冲突提交不能进入任一批次，两个批次的已有记录都应保持原样；
305	// 原编号在原批次上仍取回第一次的结果，新批次只能用自己的新编号登记。
306	func TestAddFeedingRequestNumberSharedAcrossBatches(t *testing.T) {
307		s := openTestStore(t)
308		registerStandardRecipe(t, s, "recipe-1")
309		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
310			t.Fatalf("创建 B1 失败: %v", err)
311		}
312		if _, err := s.StartBatch("s1", "B1"); err != nil {
313			t.Fatalf("开始执行 B1 失败: %v", err)
314		}
315		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
316			t.Fatalf("创建 B2 失败: %v", err)
317		}
318		if _, err := s.StartBatch("s2", "B2"); err != nil {
319			t.Fatalf("开始执行 B2 失败: %v", err)
320		}
321	
322		t1 := feedingReplayTime()
323		first, err := s.AddFeeding("shared-feed", "B1", "M1", "1.000", t1, "张三")
324		if err != nil {
325			t.Fatalf("B1 首次登记投料应成功: %v", err)
326		}
327		checkFeedingView(t, first, 1, "M1", "1", t1, "张三")
328	
329		// B2 沿用同一请求编号登记一笔本身合法的投料：必须判冲突，
330		// 不能在 B2 落下记录，也不能返回 B1 的那笔记录冒充成功。
331		_, err = s.AddFeeding("shared-feed", "B2", "M1", "1.000", t1, "张三")
332		if !errors.Is(err, ErrRequestConflict) {
333			t.Fatalf("另一批次沿用已成功的请求编号应返回 ErrRequestConflict，得到 %v", err)
334		}
335	
336		// 两个批次的已有记录都保持原样。
337		b1 := mustGetBatch(t, s, "B1")
338		if len(b1.Feedings) != 1 {
339			t.Fatalf("B1 应仍只有 1 条投料，得到 %d 条: %+v", len(b1.Feedings), b1.Feedings)
340		}
341		checkFeedingView(t, &b1.Feedings[0], 1, "M1", "1", t1, "张三")
342		b1Mats := materialsMap(b1)
343		checkRequirement(t, b1Mats, "M1", "1000", "1", "-999")
344	
345		b2 := mustGetBatch(t, s, "B2")
346		if len(b2.Feedings) != 0 {
347			t.Fatalf("冲突提交不应进入 B2，得到 %d 条: %+v", len(b2.Feedings), b2.Feedings)
348		}
349		b2Mats := materialsMap(b2)
350		checkRequirement(t, b2Mats, "M1", "500", "0", "-500") // 100×5，无投料
351		checkRequirement(t, b2Mats, "M2", "2.5", "0", "-2.5") // 0.5×5
352	
353		// 原编号在原批次上仍取回 B1 的第一次结果。
354		replay, err := s.AddFeeding("shared-feed", "B1", "M1", "1.000", t1, "张三")
355		if err != nil {
356			t.Fatalf("冲突后原编号在原批次上应仍可重放: %v", err)
357		}
358		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
359	
360		// B2 改用尚未使用的请求编号，可以正常登记自己的第一笔投料，
361		// 序号在 B2 内从 1 开始，与 B1 互不影响。
362		b2Feed, err := s.AddFeeding("b2-feed", "B2", "M1", "4", t1.Add(time.Hour), "李四")
363		if err != nil {
364			t.Fatalf("B2 用新编号登记投料应成功: %v", err)
365		}
366		checkFeedingView(t, b2Feed, 1, "M1", "4", t1.Add(time.Hour), "李四")
367		b1 = mustGetBatch(t, s, "B1")
368		if len(b1.Feedings) != 1 {
369			t.Fatalf("B2 的投料不应影响 B1，B1 应仍为 1 条，得到 %d 条", len(b1.Feedings))
370		}
371	}
372	
373	// 发生冲突后，原内容仍能用原编号取得第一次成功结果；改用尚未使用的请求
374	// 编号提交完全相同的投料内容，则表示独立的一笔投料：应正常追加、取得连续
375	// 的下一个序号，并只增加该物料的累计实投量。原编号的重放结果必须始终是
376	// 第一次那笔，不能把新追加的同内容投料误当成原记录。
377	func TestAddFeedingNewRequestSameContentAppendsIndependentFeeding(t *testing.T) {
378		s := openTestStore(t)
379		registerStandardRecipe(t, s, "recipe-1")
380		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
381			t.Fatalf("创建批次失败: %v", err)
382		}
383		if _, err := s.StartBatch("s1", "B1"); err != nil {
384			t.Fatalf("开始执行失败: %v", err)
385		}
386	
387		t1 := feedingReplayTime()
388		first, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
389		if err != nil {
390			t.Fatalf("首次登记投料应成功: %v", err)
391		}
392		checkFeedingView(t, first, 1, "M1", "1", t1, "张三")
393	
394		// 一次本身合法的冲突提交（改投同配方内另一物料），确认它不落任何记录。
395		if _, err := s.AddFeeding("feed-1", "B1", "M2", "1.000", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
396			t.Fatalf("沿用原编号改投另一物料应返回 ErrRequestConflict，得到 %v", err)
397		}
398	
399		// 原内容用原编号仍取得第一次成功结果。
400		replay, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
401		if err != nil {
402			t.Fatalf("冲突后原内容应仍可重放: %v", err)
403		}
404		checkFeedingView(t, replay, 1, "M1", "1", t1, "张三")
405	
406		// 改用尚未使用的请求编号提交与首次完全相同的投料内容：这是独立的一笔，
407		// 正常追加，取得连续的下一个序号 2（冲突没有占用序号）。
408		independent, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", t1, "张三")
409		if err != nil {
410			t.Fatalf("新请求编号提交相同内容应作为独立投料成功: %v", err)
411		}
412		checkFeedingView(t, independent, 2, "M1", "1", t1, "张三")
413	
414		// 批次现有两笔，登记顺序与各自内容清晰；只增加 M1 的实投（1+1=2），
415		// M2、M3 仍为零。
416		view := mustGetBatch(t, s, "B1")
417		if len(view.Feedings) != 2 {
418			t.Fatalf("应追加为 2 条投料，得到 %d 条: %+v", len(view.Feedings), view.Feedings)
419		}
420		checkFeedingView(t, &view.Feedings[0], 1, "M1", "1", t1, "张三")
421		checkFeedingView(t, &view.Feedings[1], 2, "M1", "1", t1, "张三")
422		mats := materialsMap(view)
423		checkRequirement(t, mats, "M1", "1000", "2", "-998")
424		checkRequirement(t, mats, "M2", "5", "0", "-5")
425		checkRequirement(t, mats, "M3", "0.1", "0", "-0.1")
426	
427		// 新投料追加后，原编号的重放结果必须仍是第一次那笔（序号 1），
428		// 不能把后来同内容的序号 2 误当成原记录。
429		replayAgain, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
430		if err != nil {
431			t.Fatalf("追加同内容投料后原编号重放应成功: %v", err)
432		}
433		checkFeedingView(t, replayAgain, 1, "M1", "1", t1, "张三")
434		// 新编号重放的是它自己的第一次结果（序号 2），两者各自独立。
435		replayNew, err := s.AddFeeding("feed-2", "B1", "M1", "1.000", t1, "张三")
436		if err != nil {
437			t.Fatalf("新编号重放应成功: %v", err)
438		}
439		checkFeedingView(t, replayNew, 2, "M1", "1", t1, "张三")
440	
441		// 两次重放都不重复计入：仍是 2 条、M1 累计 2。
442		view = mustGetBatch(t, s, "B1")
443		if len(view.Feedings) != 2 {
444			t.Fatalf("重放不应新增投料，得到 %d 条", len(view.Feedings))
445		}
446		mats = materialsMap(view)
447		checkRequirement(t, mats, "M1", "1000", "2", "-998")
448	}
449

